```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("oceny.txt");
    string przedmiot;
    int ocena;
    map<string, pair<int, int>> dane;
    while (plik >> przedmiot >> ocena) {
        dane[przedmiot].first += ocena;
        dane[przedmiot].second++;
    }
    cout << "Srednia ocen per przedmiot:" << endl;
    cout << fixed << setprecision(2);
    string bestP, worstP;
    double bestA = -1, worstA = 100;
    for (auto& p : dane) {
        double avg = (double)p.second.first / p.second.second;
        cout << "   " << p.first << ": " << avg << endl;
        if (avg > bestA) { bestA = avg; bestP = p.first; }
        if (avg < worstA) { worstA = avg; worstP = p.first; }
    }
    cout << "Przedmiot z najwyzsza srednia: " << bestP << " (" << bestA << ")" << endl;
    cout << "Przedmiot z najnizsza srednia: " << worstP << " (" << worstA << ")" << endl;
    return 0;
}
```

Weryfikacja:
- Angielski: 5+3+4+5=17, cnt=4, avg=4.25
- Matematyka: 4+5+3+4=16, cnt=4, avg=4.00
- Polski: 3+4+5+3=15, cnt=4, avg=3.75
Najwyzsza: Angielski (4.25), najnizsza: Polski (3.75)
